 readonly string Site;readonly string SettingsPath;string DatabasePath;string? Pending;string LastStatus="";readonly NativeSpeech Speech=new();readonly DesktopBranding Branding;MusicPane? MusicPlayer;Window? ProviderWindow;LocalTrialClock TrialClock=null!;bool trialActive;
 public MainWindow(){InitializeComponent();InitDeviceWatch();OwnershipText.Text="© Ahmed Morgan "+DateTime.Now.Year;var creditTimer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMinutes(1)};creditTimer.Tick+=(_,_)=>OwnershipText.Text="© Ahmed Morgan "+DateTime.Now.Year;creditTimer.Start();Closed+=(_,_)=>{creditTimer.Stop();StopMusic();};var config=Path.Combine(AppContext.BaseDirectory,"gymos.json");var url=File.Exists(config)?JsonDocument.Parse(File.ReadAllText(config)).RootElement.GetProperty("siteUrl").GetString():"https://gymeg.vercel.app";if(!Uri.TryCreate(url,UriKind.Absolute,out var uri)||uri.Scheme!="https"||!string.IsNullOrEmpty(uri.UserInfo)||uri.AbsolutePath!="/")throw new InvalidOperationException("Set an HTTPS deployment origin in gymos.json.");if(uri.Host=="gym-os-liart.vercel.app"||uri.Host=="gymos-web-pulse.bouncybowl4.chatgpt.site")uri=new Uri("https://gymeg.vercel.app");Site=uri.GetLeftPart(UriPartial.Authority);var root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"GymOS");Directory.CreateDirectory(root);TrialClock=new LocalTrialClock(root);var trialTimer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromSeconds(10)};trialTimer.Tick+=(_,_)=>CheckLocalTrial();trialTimer.Start();Closed+=(_,_)=>trialTimer.Stop();Branding=new DesktopBranding(Path.Combine(root,"Branding"));var cachedBrand=Branding.Load();if(cachedBrand!=null)ApplyBrand(cachedBrand,false);SettingsPath=Path.Combine(root,"desktop-settings.json");DatabasePath=Path.Combine(root,"Backups","gymos-backups.sqlite");if(File.Exists(SettingsPath)){try{DatabasePath=JsonDocument.Parse(File.ReadAllText(SettingsPath)).RootElement.GetProperty("backupDatabase").GetString()??DatabasePath;}catch{}}Report("Server: "+Site+" · "+DatabasePath);}

 void CheckLocalTrial(){if(!trialActive)return;bool allowed;try{allowed=TrialClock.Allowed(DateTimeOffset.UtcNow);}catch{allowed=false;}if(!allowed){trialActive=false;StopMusic();Speech.Stop();MessageBox.Show("انتهت التجربة المحلية أو تحتاج ساعة Windows للتصحيح. بيانات النادي محفوظة.\nLocal trial expired or Windows clock needs correction. Club data is retained.","GYMEG trial");if(Browser.CoreWebView2!=null)Browser.CoreWebView2.Navigate(Site+"/clubs?trial=expired-local");}}
 void StopMusic(){var window=ProviderWindow;ProviderWindow=null;MusicPlayer?.Dispose();MusicPlayer=null;window?.Close();MusicHost.Child=null;MusicHost.Visibility=Visibility.Collapsed;}
 void OpenMusic(string url,string scope){if(!MusicNavigation.Initial(url))return;StopMusic();var pane=new MusicPane(url,scope);var window=new Window{Owner=this,Title="GYMEG · "+new Uri(url).Host,Width=480,Height=680,MinWidth=360,MinHeight=400,WindowStartupLocation=WindowStartupLocation.CenterOwner,Content=pane,Icon=Icon};MusicPlayer=pane;ProviderWindow=window;pane.CloseRequested+=()=>window.Close();window.Closed+=(_,_)=>{pane.Dispose();if(ReferenceEquals(ProviderWindow,window)){ProviderWindow=null;MusicPlayer=null;}};window.Show();}
 void ApplyBrand(ClubBrand? brand,bool persist){try{if(brand==null){if(persist)Branding.Clear();var fallback=System.Windows.Media.Imaging.BitmapFrame.Create(new Uri("pack://application:,,,/GymOS;component/SplashLogo.png"));Icon=fallback;SplashLogo.Source=fallback;SplashTitle.Text="GYMEG";Title="GYMEG";if(persist)UpdateClubShortcut(null);return;}var visual=Branding.Apply(brand,persist);var image=visual.image??System.Windows.Media.Imaging.BitmapFrame.Create(new Uri("pack://application:,,,/GymOS;component/SplashLogo.png"));Icon=image;SplashLogo.Source=image;SplashTitle.Text=brand.Name;Title=brand.Name+" · GYMEG";if(persist)UpdateClubShortcut(visual.icon);}catch{/* Invalid or unavailable branding keeps the built-in logo. */}}
 void UpdateClubShortcut(string? icon){try{var desktop=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);if(string.IsNullOrEmpty(desktop))return;var shellType=Type.GetTypeFromProgID("WScript.Shell");if(shellType==null)return;dynamic shell=Activator.CreateInstance(shellType)!;var file=Path.Combine(desktop,"GYMEG.lnk");dynamic shortcut=shell.CreateShortcut(file);string existing=shortcut.TargetPath;if(!string.IsNullOrEmpty(existing)&&!Path.GetFileNameWithoutExtension(existing).StartsWith("GymOS",StringComparison.OrdinalIgnoreCase))return;shortcut.TargetPath=Environment.ProcessPath!;shortcut.WorkingDirectory=AppContext.BaseDirectory;shortcut.Description="GYMEG";shortcut.IconLocation=icon??Environment.ProcessPath!;shortcut.Save();System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shortcut);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}catch{/* Desktop shortcut updates are optional; app icon remains branded. */}}
 void Report(string text){LastStatus=text;var core=Browser?.CoreWebView2;if(core!=null&&Uri.TryCreate(Browser?.Source?.AbsoluteUri,UriKind.Absolute,out var uri)&&uri.GetLeftPart(UriPartial.Authority)==Site)core.PostWebMessageAsJson(JsonSerializer.Serialize(new{type="gymos-desktop-status",status=text,path=DatabasePath,site=Site,version="1.1.11",capabilities=new[]{"deviceInventory"}}));}
 void ChooseDatabase(object sender,RoutedEventArgs e){var dialog=new SaveFileDialog{Title="اختيار ملف قاعدة النسخ الاحتياطية / Choose backup database",Filter="SQLite database|*.sqlite",FileName="gymos-backups.sqlite",OverwritePrompt=false};if(dialog.ShowDialog()!=true)return;try{BackupStore.Initialize(dialog.FileName);DatabasePath=dialog.FileName;File.WriteAllText(SettingsPath,JsonSerializer.Serialize(new{backupDatabase=DatabasePath}));Report(DatabasePath);}catch(Exception ex){MessageBox.Show(ex.Message,"GYMEG backup");}}
 void SaveBackup(object sender,RoutedEventArgs e)=>RequestBackup("save");void ExportBackup(object sender,RoutedEventArgs e)=>RequestBackup("export");
 async void RequestBackup(string action){if(Browser.CoreWebView2==null||Pending!=null)return;if(!Uri.TryCreate(Browser.Source?.AbsoluteUri,UriKind.Absolute,out var uri)||uri.GetLeftPart(UriPartial.Authority)!=Site)return;Pending=action;Report("جارٍ التحقق من حساب المالك… / Checking owner account…");try{await Browser.CoreWebView2.ExecuteScriptAsync("(async()=>{try{const workspace=await fetch('/api/workspace',{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!workspace.ok)throw Error('Sign in as owner / سجل دخول المالك');const scope=await workspace.json();const headers={'Content-Type':'application/json','X-GymOS-Tenant':scope.owner};const start=await fetch('/api/backup',{method:'POST',headers,body:JSON.stringify({action:'downloadStart'}),signal:AbortSignal.timeout(120000)});if(!start.ok)throw Error('Backup unavailable');const m=await start.json();let data;try{if(m.bytes>67108864||m.bytes<1)throw Error('Backup too large');const bytes=new Uint8Array(m.bytes);for(let i=0;i<m.parts;i++){const r=await fetch('/api/backup?transfer='+encodeURIComponent(m.id)+'&part='+i,{cache:'no-store',headers,signal:AbortSignal.timeout(120000)});if(!r.ok)throw Error('Backup download failed');const chunk=await r.json();const part=Uint8Array.from(atob(chunk.data),c=>c.charCodeAt(0));if(part.length!==Math.min(m.chunkBytes,m.bytes-i*m.chunkBytes))throw Error('Invalid backup chunk');bytes.set(part,i*m.chunkBytes);}const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(b=>b.toString(16).padStart(2,'0')).join('');if(digest!==m.digest)throw Error('Backup integrity failed');data=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}finally{await fetch('/api/backup',{method:'POST',headers,body:JSON.stringify({action:'transferCancel',id:m.id})}).catch(()=>{});}window.chrome.webview.postMessage({type:'gymos-backup',backup:data});}catch(e){window.chrome.webview.postMessage({type:'gymos-backup-error',message:String(e)});}})()");}catch{Pending=null;Report("تعذر طلب النسخة / Backup request failed");}}
 async Task SpeakNative(string id,string text,string voice,double rate){var origin=Browser.Source?.AbsoluteUri;bool ok;try{await Speech.Speak(text,voice,rate);ok=true;}catch{ok=false;}try{if(Browser.CoreWebView2!=null&&Browser.Source?.AbsoluteUri==origin)Browser.CoreWebView2.PostWebMessageAsJson(JsonSerializer.Serialize(new{type="gymos-speech-result",id,ok}));}catch{/* window closed or navigated during playback */}}
 void ReceiveBackup(object? sender,CoreWebView2WebMessageReceivedEventArgs args){if(args.WebMessageAsJson.Length>100000000)return;if(!Uri.TryCreate(args.Source,UriKind.Absolute,out var uri)||uri.GetLeftPart(UriPartial.Authority)!=Site)return;try{using var command=JsonDocument.Parse(args.WebMessageAsJson);var message=command.RootElement;if(message.TryGetProperty("type",out var kind)&&kind.GetString()=="gymos-desktop"){if(!message.TryGetProperty("action",out var requested)||requested.ValueKind!=JsonValueKind.String)return;var name=requested.GetString();if(!DesktopCommands.Allowed(name)||args.WebMessageAsJson.Length>(name=="branding"?1500000:12000))return;switch(name){case "trial":if(message.TryGetProperty("mode",out var trialMode)&&trialMode.GetString()=="trial"){try{if(!message.TryGetProperty("serverNow",out var serverStamp)||!serverStamp.TryGetInt64(out var stamp)||Math.Abs((DateTimeOffset.UtcNow-DateTimeOffset.FromUnixTimeMilliseconds(stamp)).TotalMinutes)>5)throw new InvalidOperationException("Check Windows clock");var start=DateTimeOffset.Parse(message.GetProperty("start").GetString()!);var end=DateTimeOffset.Parse(message.GetProperty("end").GetString()!);TrialClock.Activate(start,end,DateTimeOffset.UtcNow);trialActive=true;CheckLocalTrial();}catch{trialActive=false;StopMusic();Speech.Stop();Browser.CoreWebView2.Navigate(Site+"/clubs?trial=local-check");}}else trialActive=false;break;case "musicStop":StopMusic();break;case "music":if(message.TryGetProperty("url",out var musicUrl)&&musicUrl.ValueKind==JsonValueKind.String&&message.TryGetProperty("scope",out var musicScope)&&musicScope.ValueKind==JsonValueKind.String)OpenMusic(musicUrl.GetString()!,musicScope.GetString()!);break;case "branding":if(message.TryGetProperty("clear",out var clearing)&&clearing.ValueKind==JsonValueKind.True)ApplyBrand(null,true);else if(message.TryGetProperty("owner",out var brandOwner)&&message.TryGetProperty("name",out var brandName)&&message.TryGetProperty("logo",out var brandLogo))ApplyBrand(new ClubBrand(brandOwner.GetString()!,brandName.GetString()!,brandLogo.ValueKind==JsonValueKind.Null?null:brandLogo.GetString()),true);break;case "speechVoices":Browser.CoreWebView2.PostWebMessageAsJson(JsonSerializer.Serialize(new{type="gymos-speech-voices",voices=Speech.Voices()}));break;case "speak":if(message.TryGetProperty("text",out var speechText)&&speechText.ValueKind==JsonValueKind.String&&message.TryGetProperty("voice",out var speechVoice)&&speechVoice.ValueKind==JsonValueKind.String&&message.TryGetProperty("rate",out var speechRate)&&speechRate.TryGetDouble(out var rate))_ = SpeakNative(message.TryGetProperty("id",out var requestId)&&requestId.ValueKind==JsonValueKind.String?(requestId.GetString()??"")[..Math.Min(100,requestId.GetString()!.Length)]:"",speechText.GetString()!,speechVoice.GetString()!,rate);break;case "stopSpeech":Speech.Stop();break;case "status":Report(LastStatus);break;case "chooseDatabase":ChooseDatabase(this,new RoutedEventArgs());break;case "save":RequestBackup("save");break;case "export":RequestBackup("export");break;case "refreshSignIn":RefreshSignIn(this,new RoutedEventArgs());break;case "devices":RequestDevices(message);break;case "stopDevices":StopDevices(message);break;case "soundSettings":Process.Start(new ProcessStartInfo("ms-settings:sound"){UseShellExecute=true});break;case "speechSettings":Process.Start(new ProcessStartInfo("ms-settings:speech"){UseShellExecute=true});break;}return;}}catch{return;}if(Pending==null)return;var action=Pending;Pending=null;try{if(args.WebMessageAsJson.Length>100000000)throw new InvalidOperationException("Backup too large");using var json=JsonDocument.Parse(args.WebMessageAsJson);var root=json.RootElement;if(root.GetProperty("type").GetString()!="gymos-backup")throw new InvalidOperationException("Sign in as the gym owner / سجل دخول مالك النادي");var backup=root.GetProperty("backup");if(backup.GetProperty("format").GetString()!="gymos-backup"||backup.GetProperty("version").GetInt32()!=2)throw new InvalidOperationException("Invalid backup format");var tenant=backup.GetProperty("tenant").GetString()!;if(string.IsNullOrWhiteSpace(tenant))throw new InvalidOperationException("Missing tenant");if(action=="save"){BackupStore.Save(DatabasePath,tenant,backup.GetRawText());Report("تم حفظ نسخة مشفرة / Encrypted backup saved · "+DateTime.Now.ToString("yyyy-MM-dd HH:mm")+" · "+DatabasePath);}else{var payload=BackupStore.Latest(DatabasePath,tenant);var save=new SaveFileDialog{Title="تصدير JSON للاستعادة من شاشة تشغيل النادي / Export backup",Filter="GYMEG JSON|*.json",FileName="gymos-backup-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json"};if(save.ShowDialog()==true){File.WriteAllText(save.FileName,payload);Report("تم التصدير. ملف JSON غير مشفر / Exported JSON is not encrypted");}}}catch(Exception ex){Report("تعذر النسخ / Backup failed: "+ex.Message);}}
 async void RefreshSignIn(object sender,RoutedEventArgs e){if(Browser.CoreWebView2==null)return;try{ApplyBrand(null,true);var core=Browser.CoreWebView2;var cookies=await core.CookieManager.GetCookiesAsync(Site);foreach(var cookie in cookies)if(cookie.Name.StartsWith("sb-",StringComparison.Ordinal))core.CookieManager.DeleteCookie(cookie);await core.CallDevToolsProtocolMethodAsync("Network.clearBrowserCache","{}");core.Navigate(Site+"/sign-in");Report("Server: "+Site+" · أدخل بيانات الدخول من جديد / Sign in again");}catch{Report("تعذر تجديد الجلسة / Could not refresh sign-in");}}
 async void Start(object sender,RoutedEventArgs e){try{
  var profile=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"GymOS","WebProfile");var environment=await CoreWebView2Environment.CreateAsync(null,profile);await Browser.EnsureCoreWebView2Async(environment);var core=Browser.CoreWebView2;core.Settings.AreDevToolsEnabled=false;core.Settings.IsStatusBarEnabled=false;core.Settings.AreHostObjectsAllowed=false;core.WebMessageReceived+=ReceiveBackup;
  core.NavigationStarting+=(_,args)=>{ResetDevices();Pending=null;Speech.Stop();StopMusic();if(!Uri.TryCreate(args.Uri,UriKind.Absolute,out var uri)||uri.Scheme!="https"){args.Cancel=true;return;}if(uri.GetLeftPart(UriPartial.Authority)!=Site){args.Cancel=true;Process.Start(new ProcessStartInfo(uri.AbsoluteUri){UseShellExecute=true});}};
  core.NewWindowRequested+=(_,args)=>{args.Handled=true;if(Uri.TryCreate(args.Uri,UriKind.Absolute,out var uri)&&uri.Scheme=="https"){if(uri.GetLeftPart(UriPartial.Authority)==Site)core.Navigate(uri.AbsoluteUri);else Process.Start(new ProcessStartInfo(uri.AbsoluteUri){UseShellExecute=true});}};
  core.PermissionRequested+=(_,args)=>{if(args.PermissionKind==CoreWebView2PermissionKind.Camera&&Uri.TryCreate(args.Uri,UriKind.Absolute,out var uri)&&uri.GetLeftPart(UriPartial.Authority)==Site){args.State=MessageBox.Show("السماح للكاميرا لتصوير العضو أو قراءة الكارت؟\nAllow camera for member photo / card scanning?","GYMEG",MessageBoxButton.YesNo,MessageBoxImage.Question)==MessageBoxResult.Yes?CoreWebView2PermissionState.Allow:CoreWebView2PermissionState.Deny;}else args.State=CoreWebView2PermissionState.Deny;};
  core.NavigationCompleted+=(_,args)=>{Splash.Visibility=args.IsSuccess?Visibility.Collapsed:Visibility.Visible;Status.Text=args.IsSuccess?"":"تعذر الاتصال. تحقق من الإنترنت.\nConnection unavailable. Check internet.";};Closing+=(_,_)=>{StopMusic();Speech.Dispose();};core.Navigate(Site);
 }catch(Exception ex){Splash.Visibility=Visibility.Visible;Status.Text="يلزم Microsoft Edge WebView2 Runtime.\nInstall Microsoft Edge WebView2 Runtime.\n"+ex.Message;}}
